function lookupChordVoicing(chordData) {
    const entry = CHORD_DB[chordData];
    if (entry && Array.isArray(entry.v) && entry.v.length > 0) {
        return entry.v;
    }
    return null;
}

/**
 * Many different clients write to a room (Dashboard, NotesChordScales, ...)
 * and not all of them update chordInfo when they update chordData. A stale
 * chordInfo from an earlier session must be ignored, or the device plays the
 * same old chord forever. chordInfo is only trusted when its id matches the
 * current chordData.
 */
function chordInfoMatches(doc, chordData) {
    try {
        const id = extractFieldValue(doc.fields.chordInfo.mapValue.fields.id);
        return typeof id === 'string' && id === chordData;
    } catch (e) {
        return false;
    }
}

/**
 * Resolve the MIDI voicing for the current chord.
 * Priority: room's chordInfo.voicing IF it matches chordData (exact, supports
 *           custom chords)
 *           → inlined chord DB voicing
 *           → null (display-only)
 */
function resolveChordNotes(doc, chordData) {
    if (chordInfoMatches(doc, chordData)) {
        const chordInfoVoicing = extractChordInfoVoicing(doc);
        if (chordInfoVoicing) return chordInfoVoicing;
    } else if (doc.fields && doc.fields.chordInfo) {
        maxApi.post(`Stale chordInfo ignored (id != "${chordData}"); using chord DB`);
    }
    return lookupChordVoicing(chordData);
}

/**
 * Resolve the pitch class (0-11) of the current chord's root.
 * Priority: chordInfo.root (if chordInfo matches chordData)
 *           → inlined chord DB root
 *           → chord symbol prefix ("a_m7-13" → 9)
 */
function resolveChordRoot(doc, chordData) {
    if (chordInfoMatches(doc, chordData)) {
        const infoRoot = extractChordInfoRoot(doc);
        if (infoRoot !== null) return infoRoot;
    }
    const entry = CHORD_DB[chordData];
    if (entry && typeof entry.r === 'number') return entry.r;
    if (typeof chordData === 'string') {
        const underscoreIndex = chordData.indexOf('_');
        if (underscoreIndex > 0) {
            const root = ROOT_TO_MIDI[chordData.substring(0, underscoreIndex).toLowerCase()];
            if (root !== undefined) return root;
        }
    }
    return null;
}

// ---------------------------------------------------------------------------
// Stack White MIDI Instrument
//
// Ported from Tonalign (Source/PluginProcessor.cpp):
//   - getWhiteKeyIndex        (:399-427)  white-key indexing, black keys -> -1
//   - getWhiteKeyStackedMidiNote (:429-465)  degree = index % len, +12/cycle
//   - note bookkeeping        (:245-278)  NoteMapping{original,remapped,ch,vel}
//   - checkUpdateNoteMappings (:287-299)  remap held notes on harmony change
//                                         (Interrupt behavior, always on here)
//
// Documented deviation: Tonalign anchors white-key index 0 at MIDI 0. The
// Bridge re-anchors so input C4 (MIDI 60) always plays palette[0], and the
// palette itself is voiced near C4 (spec: "normalize first note around 60").
// ---------------------------------------------------------------------------

// Tonalign pcToWhiteKey: white keys C D E F G A B -> 0..6, black keys -> -1
const PC_TO_WHITE_KEY = [0, -1, 1, -1, 2, 3, -1, 4, -1, 5, -1, 6];

// Total white-key index (octave * 7 + position), or -1 for black keys
function whiteKeyIndex(midiNote) {
    const wk = PC_TO_WHITE_KEY[((midiNote % 12) + 12) % 12];
    if (wk < 0) return -1;  // black key - blocked (Tonalign behavior)
    return Math.floor(midiNote / 12) * 7 + wk;
}

const WK_C4 = whiteKeyIndex(60);  // input C4 = palette position 0

// Place a pitch class in the octave nearest C3 (result in 42-53)
function placeNear48(pc) {
    const p = ((pc % 12) + 12) % 12;
    return p <= 5 ? 48 + p : 36 + p;
}

/**
 * Ascending close-position palette from pitch classes, starting at the root
 * placed nearest C3. Cmaj7 pcs {0,4,7,11} root 0 -> [48, 52, 55, 59].
 */
function paletteFromPcs(pcs, rootPc) {
    if (!pcs || pcs.length === 0) return null;
    const uniq = [...new Set(pcs.map(pc => ((pc % 12) + 12) % 12))].sort((a, b) => a - b);
    let root = (rootPc === null || rootPc === undefined) ? uniq[0] : ((rootPc % 12) + 12) % 12;
    if (uniq.indexOf(root) === -1) root = uniq[0];
    const start = uniq.indexOf(root);
    const palette = [placeNear48(root)];
    let prevPc = root;
    for (let i = 1; i < uniq.length; i++) {
        const pc = uniq[(start + i) % uniq.length];
        palette.push(palette[palette.length - 1] + (((pc - prevPc) + 12) % 12));
        prevPc = pc;
    }
    return palette;
}

/**
 * Scale palette: the scale's pitch classes placed in a fixed C3-B3 window,
 * sorted ascending. Anchored at C (NOT the scale root) so parsimonious scale
 * changes in the 57-network move as few keys as possible: pitch classes
 * shared between consecutive scales usually stay on the same keys; only the
 * changed scale tones move.
 */
function paletteFromWindow(pcs) {
    if (!pcs || pcs.length === 0) return null;
    const uniq = [...new Set(pcs.map(pc => ((pc % 12) + 12) % 12))].sort((a, b) => a - b);
    return uniq.map(pc => 48 + pc);
}

/**
 * Root-mode fifth: interval above the root of the chord tone nearest a
 * perfect fifth (7 semitones). Ties pick the higher tone (root+8 over the
 * root+6 tritone). 0 (the root itself) if the chord has no other tones.
 */
function fifthInterval(rootPc, chordPcs) {
    if (!chordPcs || chordPcs.length === 0) return 0;
    let best = null;
    for (const pc of new Set(chordPcs.map(p => ((p % 12) + 12) % 12))) {
        const iv = ((pc - rootPc) + 12) % 12;
        if (iv === 0) continue;
        if (best === null || Math.abs(iv - 7) < Math.abs(best - 7) ||
            (Math.abs(iv - 7) === Math.abs(best - 7) && iv > best)) best = iv;
    }
    return best === null ? 0 : best;
}

/**
 * The palette for this device's NoteSource, from current harmony state.
 * null = nothing playable (no harmony yet, or display-only chord).
 */
function currentPalette() {
    switch (noteSource) {
        case 1: {  // Root: A S D = root (near C2), F G H = fifth, J K L = root +12
            if (currentChordRoot === null) return null;
            const r = placeNear48(currentChordRoot) - 12;
            const f = r + fifthInterval(currentChordRoot,
                currentChordNotes ? currentChordNotes.map(n => n % 12) : null);
            return [r, r, r, f, f, f];
        }
        case 2:  // Scale: scale tones in a fixed C octave window, sorted
            return currentScalePcs ? paletteFromWindow(currentScalePcs) : null;
        default: // Chord: chord pitch classes, close position from harmonic root
            return currentChordNotes
                ? paletteFromPcs(currentChordNotes.map(n => n % 12), currentChordRoot)
                : null;
    }
}

/**
 * Map an incoming MIDI pitch to an output pitch (Tonalign Stack White,
 * re-anchored at C4). Returns -1 for blocked input (black key, no palette,
 * or out of MIDI range).
 */
function mapInputToOutput(inputPitch) {
    const wk = whiteKeyIndex(inputPitch);
    if (wk < 0) return -1;
    const palette = currentPalette();
    if (!palette) return -1;
    const rel = wk - WK_C4;
    const len = palette.length;
    let out;
    if (len === 1) {
        // Single-note palette: every white key in a row plays the same note;
        // each row up/down shifts an octave. (An octave-per-key mapping would
        // leave most of the keyboard outside MIDI range.)
        out = palette[0] + 12 * Math.floor(rel / 7);
    } else {
        const degree = ((rel % len) + len) % len;
        out = palette[degree] + 12 * Math.floor(rel / len);
    }
    return (out >= 0 && out <= 127) ? out : -1;
}

function sendMidi(pitch, velocity) {
    maxApi.outlet('midiNote', pitch, velocity);
}

// Is this output pitch held by any active mapping?
function outputInUse(pitch) {
    return activeNotes.some(n => n.outputPitch === pitch);
}

function noteOn(inputPitch, velocity, channel) {
    // Retriggered input without a note-off: release the old mapping first
    noteOff(inputPitch, channel);
    const out = mapInputToOutput(inputPitch);
    if (out < 0) return;  // blocked - no output; its note-off will be dropped
    if (!outputInUse(out)) sendMidi(out, velocity);  // refcount: no duplicate note-ons
    activeNotes.push({ inputPitch, outputPitch: out, velocity, channel });
}

function noteOff(inputPitch, channel) {
    for (let i = 0; i < activeNotes.length; i++) {
        const n = activeNotes[i];
        if (n.inputPitch === inputPitch && n.channel === channel) {
            activeNotes.splice(i, 1);
            // refcount: only silence the output when no other input holds it
            if (!outputInUse(n.outputPitch)) sendMidi(n.outputPitch, 0);
            return;
        }
    }
    // Untracked note-off (input was blocked at note-on) - drop it, like Tonalign
}

/**
 * Harmony or NoteSource changed while notes are held: re-pitch every held
 * input against the new palette (Tonalign checkUpdateNoteMappings, Interrupt
 * always on). Note-offs are emitted before note-ons; outputs that survive
 * unchanged are left sounding (no duplicate note-ons, no orphaned note-offs).
 */
function remapActiveNotes() {
    if (activeNotes.length === 0) return;
    const oldSounding = new Set(activeNotes.map(n => n.outputPitch));
    const next = [];
    for (const n of activeNotes) {
        const out = mapInputToOutput(n.inputPitch);
        // out < 0: input no longer playable (palette gone) - drop the mapping
        if (out >= 0) next.push({ inputPitch: n.inputPitch, outputPitch: out, velocity: n.velocity, channel: n.channel });
    }
    const newSounding = new Set(next.map(n => n.outputPitch));
    for (const p of oldSounding) {
        if (!newSounding.has(p)) sendMidi(p, 0);   // note-off first (Tonalign order)
    }
    const sent = new Set();
    for (const n of next) {
        const p = n.outputPitch;
        if (oldSounding.has(p) || sent.has(p)) continue;
        sendMidi(p, n.velocity);
        sent.add(p);
    }
    activeNotes = next;
}

// Release everything: note-offs for all sounding outputs, clear bookkeeping
function flushAllNotes() {
    const sounding = new Set(activeNotes.map(n => n.outputPitch));
    for (const p of sounding) sendMidi(p, 0);
    activeNotes = [];
}

// ---------------------------------------------------------------------------
// Firestore REST API
// ---------------------------------------------------------------------------

function buildFirestoreUrl(docId) {
    if (!docId) return null;
    return `https://firestore.googleapis.com/v1/projects/${config.projectId}/databases/(default)/documents/rooms/${docId}`;
}

function buildQueryUrl() {
    return `https://firestore.googleapis.com/v1/projects/${config.projectId}/databases/(default)/documents:runQuery`;
}

function httpGet(url) {
    return new Promise((resolve, reject) => {
        https.get(url, (res) => {
            let data = '';
            res.on('data', chunk => data += chunk);
            res.on('end', () => resolve({ status: res.statusCode, data }));
        }).on('error', reject);
    });
}

function httpPost(url, body) {
    return new Promise((resolve, reject) => {
        const urlObj = new URL(url);
        const options = {
            hostname: urlObj.hostname,
            path: urlObj.pathname + urlObj.search,
            method: 'POST',
            headers: { 'Content-Type': 'application/json' }
        };
        const req = https.request(options, (res) => {
            let data = '';
            res.on('data', chunk => data += chunk);
            res.on('end', () => resolve({ status: res.statusCode, data }));
        });
        req.on('error', reject);
        req.write(JSON.stringify(body));
        req.end();
    });
}

// Lobby: cached list of rooms [{ id, name, updated }], most recent first
let roomList = [];

function buildRoomListUrl() {
    return `https://firestore.googleapis.com/v1/projects/${config.projectId}/databases/(default)/documents/rooms?pageSize=300&mask.fieldPaths=roomName`;
}

async function fetchRoomList() {
    const res = await httpGet(buildRoomListUrl());
    if (res.status !== 200) throw new Error(`HTTP ${res.status}`);
    const docs = JSON.parse(res.data).documents || [];
    const list = docs.map(d => {
        const id = d.name.split('/').pop();
        let name = id;
        try {
            const n = d.fields.roomName.stringValue;
            if (n) name = n;
        } catch (e) { /* no roomName field */ }
        return { id, name, updated: d.updateTime || '' };
    });
    list.sort((a, b) => (a.updated < b.updated ? 1 : -1));
    roomList = list;
    return list;
}

async function resolveRoomId(slugOrId) {
    // 1. Try direct document ID lookup
    const directUrl = buildFirestoreUrl(slugOrId);
    const directRes = await httpGet(directUrl);
    if (directRes.status === 200) {
        return slugOrId;
    }

    // 2. Query by slug field
    const queryBody = {
        structuredQuery: {
            from: [{ collectionId: 'rooms' }],
            where: {
                fieldFilter: {
                    field: { fieldPath: 'slug' },
                    op: 'EQUAL',
                    value: { stringValue: slugOrId }
                }
            },
            limit: 1
        }
    };
    const queryRes = await httpPost(buildQueryUrl(), queryBody);
    if (queryRes.status === 200) {
        try {
            const results = JSON.parse(queryRes.data);
            if (results.length > 0 && results[0].document) {
                // Extract doc ID from document name path
                const docName = results[0].document.name;
                const docId = docName.split('/').pop();
                return docId;
            }
        } catch (e) {
            // Query failed, fall through
        }
    }

    // 3. Match by roomName (case-insensitive) against the room list, so users
    // can type/paste the ensemble name shown in the Rehearse/NCS apps.
    // Most recently updated room wins on duplicate names.
    try {
        const list = await fetchRoomList();
        const target = slugOrId.trim().toLowerCase();
        const match = list.find(r => r.name.trim().toLowerCase() === target);
        if (match) {
            return match.id;
        }
    } catch (e) {
        // List failed, fall through
    }

    return null;
}

async function fetchRoomDocument() {
    if (!config.roomCode) {
        throw new Error('No room code set');
    }

    // Resolve slug to doc ID on first call or if room changed
    if (!config.resolvedDocId) {
        config.resolvedDocId = await resolveRoomId(config.roomCode);
        if (!config.resolvedDocId) {
            throw new Error(`Room "${config.roomCode}" not found`);
        }
        maxApi.post(`Resolved room "${config.roomCode}" to doc ID "${config.resolvedDocId}"`);
    }

    const url = buildFirestoreUrl(config.resolvedDocId);
    const res = await httpGet(url);

    if (res.status === 200) {
        return JSON.parse(res.data);
    } else if (res.status === 404) {
        // Room was deleted? Clear cache and retry resolution next poll
        config.resolvedDocId = null;
        throw new Error(`Room "${config.roomCode}" not found`);
    } else {
        throw new Error(`HTTP ${res.status}`);
    }
}

/**
 * Extract a field value from Firestore REST response
 * Firestore wraps values: { "integerValue": "120" } or { "stringValue": "foo" }
 */
function extractFieldValue(field) {
    if (!field) return null;
    if (field.integerValue !== undefined) return parseInt(field.integerValue, 10);
    if (field.doubleValue !== undefined) return parseFloat(field.doubleValue);
    if (field.stringValue !== undefined) return field.stringValue;
    if (field.booleanValue !== undefined) return field.booleanValue;
    return null;
}

function extractBpm(doc) {
    const fields = doc.fields;
    if (!fields || !fields.bpm) return null;
    return extractFieldValue(fields.bpm);
}

function extractScaleData(doc) {
    const fields = doc.fields;
    if (!fields || !fields.scaleData) return null;
    return extractFieldValue(fields.scaleData);
}

function extractChordData(doc) {
    const fields = doc.fields;
    if (!fields || !fields.chordData) return null;
    return extractFieldValue(fields.chordData);
}

/**
 * Extract chordInfo.voicing (array of absolute MIDI notes) from the room doc.
 * Written by Dashboard "Harmony Payload v2" alongside chordData.
 */
function extractChordInfoVoicing(doc) {
    try {
        const values = doc.fields.chordInfo.mapValue.fields.voicing.arrayValue.values;
        const notes = values
            .map(v => extractFieldValue(v))
            .filter(n => typeof n === 'number' && n >= 0 && n <= 127);
        return notes.length > 0 ? notes : null;
    } catch (e) {
        return null;
    }
}

/**
 * Extract chordInfo.root (pitch class 0-11) from the room doc, if present.
 */
function extractChordInfoRoot(doc) {
    try {
        const root = extractFieldValue(doc.fields.chordInfo.mapValue.fields.root);
        if (typeof root === 'number' && root >= 0 && root <= 11) return root;
        return null;
    } catch (e) {
        return null;
    }
}

// ---------------------------------------------------------------------------
// Polling Logic
// ---------------------------------------------------------------------------

async function poll() {
    if (!config.enabled || !config.roomCode) return;

    // Capture generation before async work to detect stale callbacks
    const myGeneration = connectionGeneration;

    try {
        const doc = await fetchRoomDocument();

        // Check if connection changed while we were waiting
        if (myGeneration !== connectionGeneration) {
            maxApi.post('Poll result discarded (connection changed)');
            return;
        }

        // --- BPM ---
        const bpm = extractBpm(doc);
        if (bpm !== null && bpm !== lastBpm) {
            lastBpm = bpm;
            maxApi.outlet('bpm', bpm);
            maxApi.post(`BPM: ${bpm}`);
        }

        // --- Scale Data → Direct to Ableton Scale Awareness ---
        const scaleData = extractScaleData(doc);
        if (scaleData !== null && scaleData !== lastScaleData) {
            lastScaleData = scaleData;
            const parsed = parseScaleData(scaleData);

            if (parsed) {
                // Send root_note for live.object (0-11)
                maxApi.outlet('rootNote', parsed.root);

                // Send display info (Scale Navigator vocabulary)
                maxApi.outlet('rootName', parsed.rootName);
                const display = SCALE_CLASS_DISPLAY[parsed.scaleClass] || parsed.scaleClass;
                maxApi.outlet('scaleClass', display);

                // Send scale_name for live.object (exact Ableton string)
                maxApi.outlet('scaleName', parsed.abletonScaleName);
                const approx = parsed.scaleClass === 'hexatonic' ? ' (superset approximation)' : '';
                maxApi.post(`Scale: ${parsed.rootName} ${display} → Ableton ${parsed.abletonScaleName}${approx}`);

                // Cache scale pitch classes + root for the Scale palette
                const intervals = SCALE_CLASS_INTERVALS[parsed.scaleClass];
                currentScalePcs = intervals
                    ? intervals.map(iv => (parsed.root + iv) % 12).sort((a, b) => a - b)
                    : null;
                remapActiveNotes();  // re-pitch held notes against the new scale
            }
        }

        // --- Chord Data → display + MIDI notes into the track ---
        const chordData = extractChordData(doc);
        if (chordData !== null && chordData !== lastChordData) {
            lastChordData = chordData;
            maxApi.outlet('chord', chordData);

            currentChordNotes = resolveChordNotes(doc, chordData);
            currentChordRoot = resolveChordRoot(doc, chordData);
            remapActiveNotes();  // re-pitch held notes against the new chord
            if (currentChordNotes) {
                maxApi.post(`Chord: ${chordData} → pcs [${currentChordNotes.map(n => n % 12).join(' ')}]`);
            } else {
                maxApi.post(`Chord: ${chordData} (no voicing found, display only)`);
            }
        }

        setStatus('connected');
        // Output roomcode so the patch can show room-specific status
        maxApi.outlet('roomcode', config.roomCode);
    } catch (err) {
        // Check if connection changed while we were waiting
        if (myGeneration !== connectionGeneration) {
            maxApi.post('Poll error discarded (connection changed)');
            return;
        }
        setStatus('error');
        maxApi.post(`Error: ${err.message}`);
    }
}

function startPolling() {
    stopPolling();
    if (config.roomCode) {
        // Increment generation for the new connection
        connectionGeneration++;
        config.enabled = true;
        setStatus('ready');  // banner shows "connecting..." until first poll lands
        poll();  // Immediate first poll
        pollTimer = setInterval(poll, config.pollInterval);
        maxApi.post(`Polling room "${config.roomCode}" every ${config.pollInterval}ms`);
    }
}

function stopPolling() {
    // Increment generation to invalidate any in-flight async poll callbacks
    connectionGeneration++;

    config.enabled = false;
    if (pollTimer) {
        clearInterval(pollTimer);
        pollTimer = null;
    }
    flushAllNotes();
    currentChordNotes = null;
    currentChordRoot = null;
    currentScalePcs = null;
    lastBpm = null;
    lastScaleData = null;
    lastChordData = null;

    // Output clear values so the patch can reset displays
    maxApi.outlet('roomcode', '');  // empty roomcode signals disconnected
    maxApi.outlet('bpm', 120);      // default BPM
    maxApi.outlet('rootName', '');  // clear scale root
    maxApi.outlet('scaleClass', ''); // clear scale class
    maxApi.outlet('chord', '');     // clear chord
}

// ---------------------------------------------------------------------------
// Max Message Handlers
// ---------------------------------------------------------------------------

maxApi.addHandler('room', (...parts) => {
    // Room names can contain spaces ("Dylan's Band") and arrive as multiple args
    const code = parts.filter(p => p !== undefined && p !== null)
        .map(p => String(p)).join(' ').trim();
    if (!code) {
        config.roomCode = null;
        config.resolvedDocId = null;
        stopPolling();
        setStatus('idle');
        maxApi.post('Room code cleared');
        return;
    }
    config.roomCode = code;
    config.resolvedDocId = null;  // Clear cached doc ID for re-resolution
    maxApi.post(`Room code set to "${code}"`);
    startPolling();  // Auto-connect whenever a room is set
});

// Lobby: fetch all ensembles and populate the device's dropdown
maxApi.addHandler('refreshRooms', async () => {
    try {
        const list = await fetchRoomList();
        maxApi.outlet('rooms', 'clear');
        for (const r of list) {
            maxApi.outlet('rooms', 'append', r.name);
        }
        maxApi.post(`Lobby: ${list.length} ensembles`);
    } catch (err) {
        maxApi.post(`Lobby refresh failed: ${err.message}`);
    }
});

// Lobby: connect to the Nth room in the last-fetched list (dropdown index)
maxApi.addHandler('selectRoom', (index) => {
    const i = parseInt(index, 10);
    if (isNaN(i) || i < 0 || i >= roomList.length) return;
    const r = roomList[i];
    config.roomCode = r.id;
    config.resolvedDocId = r.id;  // already resolved, skip lookup
    maxApi.outlet('roomcode', r.name);  // patch mirrors into the room field (persisted)
    maxApi.post(`Room selected from lobby: "${r.name}" (${r.id})`);
    startPolling();
});

maxApi.addHandler('project', (projectId) => {
    config.projectId = projectId;
    maxApi.post(`Project ID set to "${projectId}"`);
});

maxApi.addHandler('interval', (ms) => {
    config.pollInterval = Math.max(500, parseInt(ms, 10));  // Min 500ms
    maxApi.post(`Poll interval set to ${config.pollInterval}ms`);
    if (config.enabled) {
        startPolling();  // Restart with new interval
    }
});

maxApi.addHandler('connect', () => {
    if (!config.roomCode) {
        maxApi.post('Cannot connect: no room code set');
        setStatus('error');
        return;
    }
    startPolling();
});

maxApi.addHandler('disconnect', () => {
    stopPolling();
    setStatus('disconnected');
    maxApi.post('Disconnected');
});

// Incoming MIDI note from the track (midiparse -> pack pitch vel ch).
// Velocity 0 note-on is treated as note-off. Channel defaults to 1.
maxApi.addHandler('noteIn', (pitch, velocity, channel) => {
    const p = parseInt(pitch, 10);
    const v = parseInt(velocity, 10);
    const ch = (channel === undefined) ? 1 : parseInt(channel, 10) || 1;
    if (isNaN(p) || isNaN(v) || p < 0 || p > 127) return;
    if (v > 0) noteOn(p, v, ch);
    else noteOff(p, ch);
});

// Incoming CC from the track (value, controller number - Max ctl order).
// CC123 (All Notes Off) clears bookkeeping and flushes generated notes.
maxApi.addHandler('ccIn', (value, controller) => {
    if (parseInt(controller, 10) === 123) flushAllNotes();
});

// Panic / cleanup from the patch (e.g. on device delete or transport stop)
maxApi.addHandler('flush', () => {
    flushAllNotes();
});

// NoteSource (from device dropdown): 0 = Chord, 1 = Root, 2 = Scale.
// Message name stays 'mode' to match the existing patch wiring.
maxApi.addHandler('mode', (m) => {
    const mode = parseInt(m, 10);
    if (isNaN(mode) || mode < 0 || mode >= NOTE_SOURCES.length || mode === noteSource) return;
    noteSource = mode;
    maxApi.post(`NoteSource: ${NOTE_SOURCES[mode]}`);
    remapActiveNotes();  // re-pitch held notes against the new palette
});

// Manual poll (for testing)
maxApi.addHandler('poll', () => {
    poll();
});

// Report current config
maxApi.addHandler('info', () => {
    maxApi.post(`Config: room=${config.roomCode}, project=${config.projectId}, interval=${config.pollInterval}ms, enabled=${config.enabled}`);
});

// ---------------------------------------------------------------------------
// Initialization
// ---------------------------------------------------------------------------

maxApi.post('Firestore Bridge loaded');

// No room is set at load time. The patch supplies one:
// - LALORK build: loadbang -> "room la-laptop-orchestra"
// - Ensemble Bridge: pattr-persisted textedit -> "room <code>"
// Receiving a room code auto-connects (see 'room' handler above).
setStatus('idle');

// Tell the patch the script is running and handlers are registered, so it can
// safely deliver the room code (loadbang messages can arrive before the
// script starts; this closes that race).
maxApi.outlet('loaded', 1);
